command.code:
"PREVIEW - nothing is changed and no file is written."
""
"Step 1 - machine settings (admin):"
"  - Search and Widgets taskbar policies (Pro or higher)"
"  - High Performance power plan, named for the Windows language (created and tuned if missing)"
"    display off: 15 min on AC / 10 min on battery; sleep: never on AC / after 1 hour on battery"
"  - System Protection on, up to 5% disk space for restore points"
"  - Startup and Recovery: no automatic restart, write an event to the system log"
"  - 'Change brightness based on content' off (where the display supports it)"
"  - Network discovery and File and printer sharing on (Domain and Private profiles)"
"Step 2 - user settings (signed-in user):"
"  - Dark mode, built-in wallpaper, File Explorer opens to This PC with Compact view"
"  - Taskbar Search, Widgets, Task View hidden; Start menu: no recent items, All apps as a list; Explorer restarts"
"Step 3 - Windows Update window: Microsoft products, latest updates and optional-updates options on, then Check for updates"
"Step 4 - Optional updates page: select everything and click Download & install (run after the check finishes)"
"Step 5 - browser searches: chrome, Adobe Reader, the graphics driver for the detected GPU, 7-Zip"
"Step 6 - Installed apps page"
""
"Current state of this PC:"
function Show([string]$Label, $Text) { "  {0,-38} {1}" -f $Label, $Text }
$os = Get-CimInstance Win32_OperatingSystem
Show 'Windows' ($os.Caption + ' (build ' + $os.BuildNumber + ')')
if ([int]$os.BuildNumber -lt 22000 -or $os.ProductType -ne 1) { Show 'Supported by this setup' 'NO - Windows 11 client editions only' } else { Show 'Supported by this setup' 'yes' }
Show 'Domain joined' ((Get-CimInstance Win32_ComputerSystem).PartOfDomain)
$me = [Security.Principal.WindowsIdentity]::GetCurrent().Name
$active = [string](Get-CimInstance Win32_ComputerSystem).UserName
Show 'This run / signed-in user' ($me + ' / ' + $active)
if ($active -and $me -ne $active) { Show 'Per-user steps' 'WOULD BE REFUSED (different account)' } else { Show 'Per-user steps' 'would run for this user' }
$pz = Get-ItemProperty 'HKCU:\Software\Microsoft\Windows\CurrentVersion\Themes\Personalize' -ErrorAction SilentlyContinue
$ex = Get-ItemProperty 'HKCU:\Software\Microsoft\Windows\CurrentVersion\Explorer\Advanced' -ErrorAction SilentlyContinue
$se = Get-ItemProperty 'HKCU:\Software\Microsoft\Windows\CurrentVersion\Search' -ErrorAction SilentlyContinue
$st = Get-ItemProperty 'HKCU:\Software\Microsoft\Windows\CurrentVersion\Start' -ErrorAction SilentlyContinue
if ($pz.AppsUseLightTheme -eq 0) { Show 'Apps theme' 'dark' } else { Show 'Apps theme' 'light / not set' }
if ($ex.LaunchTo -eq 1) { Show 'File Explorer opens to' 'This PC' } else { Show 'File Explorer opens to' 'not This PC' }
if ($ex.UseCompactMode -eq 1) { Show 'Explorer Compact view' 'on' } else { Show 'Explorer Compact view' 'off' }
if ($se.SearchboxTaskbarMode -eq 0) { Show 'Taskbar Search' 'hidden' } else { Show 'Taskbar Search' 'shown' }
if ($ex.TaskbarDa -eq 0) { Show 'Taskbar Widgets' 'hidden' } else { Show 'Taskbar Widgets' 'shown / not set' }
if ($ex.ShowTaskViewButton -eq 0) { Show 'Taskbar Task View' 'hidden' } else { Show 'Taskbar Task View' 'shown / not set' }
if ($ex.Start_TrackDocs -eq 0) { Show 'Start: recent items' 'hidden' } else { Show 'Start: recent items' 'shown / not set' }
if ($st.ShowRecentList -eq 0) { Show 'Start: recently added apps' 'hidden' } else { Show 'Start: recently added apps' 'shown / not set' }
$modes = @{0 = 'category'; 1 = 'grid'; 2 = 'list'}
if ($null -ne $st.AllAppsViewMode) { Show 'Start: All apps view' $modes[[int]$st.AllAppsViewMode] } else { Show 'Start: All apps view' 'not set (default)' }
function Get-PowerValue([string]$Sub, [string]$Setting, [bool]$Ac) {
  $out = powercfg /query SCHEME_CURRENT $Sub $Setting 2>&1 | Out-String
  $m = [regex]::Matches($out, '0x[0-9a-fA-F]{8}')
  if ($m.Count -ge 2) {
    $i = $m.Count - 1; if ($Ac) { $i = $m.Count - 2 }
    return [int64][Convert]::ToInt64($m[$i].Value.Substring(2), 16)
  }
  return $null
}
function Get-ActiveScheme {
  $out = powercfg /getactivescheme 2>&1 | Out-String
  $g = [regex]::Match($out, '[0-9a-fA-F]{8}(?:-[0-9a-fA-F]{4}){3}-[0-9a-fA-F]{12}').Value
  if ($g) { return $g }
  return $null
}
Show 'Active power plan GUID' (Get-ActiveScheme)
foreach ($row in @(@('Display off after, AC (min)', 'SUB_VIDEO', 'VIDEOIDLE', $true), @('Display off after, battery (min)', 'SUB_VIDEO', 'VIDEOIDLE', $false), @('Sleep after, AC (min, 0 = never)', 'SUB_SLEEP', 'STANDBYIDLE', $true), @('Sleep after, battery (min)', 'SUB_SLEEP', 'STANDBYIDLE', $false))) {
  $v = Get-PowerValue $row[1] $row[2] $row[3]
  if ($null -ne $v) { Show $row[0] ([string][math]::Round($v / 60)) }
}
$cc = Get-ItemProperty 'HKLM:\SYSTEM\CurrentControlSet\Control\CrashControl' -ErrorAction SilentlyContinue
Show 'Automatic restart after a crash (1 = on)' $cc.AutoReboot
Show 'Write crash event to system log (1 = on)' $cc.LogEvent
Show 'Brightness based on content (0 = off)' (Get-ItemProperty 'HKLM:\SYSTEM\CurrentControlSet\Control\GraphicsDrivers' -ErrorAction SilentlyContinue).CABCOption
$mu = Get-ItemProperty 'HKLM:\SOFTWARE\Microsoft\WindowsUpdate\UX\Settings' -ErrorAction SilentlyContinue
Show 'Microsoft Update (other products)' $mu.AllowMUUpdateService
Show 'Latest updates as soon as available' $mu.IsContinuousInnovationOptedIn
Show 'Saved user backup' (Test-Path -LiteralPath (Join-Path $env:LOCALAPPDATA 'ToolsSetupBackup\user.json'))
Show 'Saved machine backup' (Test-Path -LiteralPath (Join-Path $env:ProgramData 'ToolsSetupBackup\machine.json'))

$os = Get-CimInstance Win32_OperatingSystem
$cs = Get-CimInstance Win32_ComputerSystem
if ([int]$os.BuildNumber -lt 22000 -or $os.ProductType -ne 1) {
  "Stopped: this setup is for Windows 11 client editions (found: " + $os.Caption + ")."
  $global:LASTEXITCODE = 1
} else {
  $isPro = $os.Caption -match 'Pro|Enterprise|Education|IoT'
  $domain = [bool]$cs.PartOfDomain
  $errors = New-Object System.Collections.Generic.List[string]
  $warn = New-Object System.Collections.Generic.List[string]
  $dir = Join-Path $env:ProgramData 'ToolsSetupBackup'
  $file = Join-Path $dir 'machine.json'
  New-Item -ItemType Directory -Path $dir -Force | Out-Null
function Get-RegSnap([string]$Path, [string]$Name) {
  $exists = $false; $value = $null; $kind = $null
  try { if (Test-Path -LiteralPath $Path) { $key = Get-Item -LiteralPath $Path; if ($key.GetValueNames() -contains $Name) { $exists = $true; $value = $key.GetValue($Name, $null, 'DoNotExpandEnvironmentNames'); $kind = $key.GetValueKind($Name).ToString() } } } catch { }
  [pscustomobject]@{ Path = $Path; Name = $Name; Exists = $exists; Value = $value; Kind = $kind }
}
function Set-Dword([string]$Path, [string]$Name, [int]$Value) {
  if (-not (Test-Path -LiteralPath $Path)) { New-Item -Path $Path -Force -ErrorAction Stop | Out-Null }
  New-ItemProperty -LiteralPath $Path -Name $Name -Value $Value -PropertyType DWord -Force -ErrorAction Stop | Out-Null
}
function Restore-RegSnap($Item) {
  if ($Item.Exists) {
    if (-not (Test-Path -LiteralPath $Item.Path)) { New-Item -Path $Item.Path -Force -ErrorAction Stop | Out-Null }
    $kind = 'String'; if ($Item.Kind) { $kind = $Item.Kind }
    New-ItemProperty -LiteralPath $Item.Path -Name $Item.Name -Value $Item.Value -PropertyType $kind -Force -ErrorAction Stop | Out-Null
  } else { Remove-ItemProperty -LiteralPath $Item.Path -Name $Item.Name -ErrorAction SilentlyContinue }
}
function Step([string]$Name, [scriptblock]$Body) {
  try {
    $o = @(& $Body)
    "[ OK ] $Name"
    foreach ($l in $o) { if ("$l".Trim().Length -gt 0) { "         $l" } }
  } catch { $errors.Add($Name + ': ' + $_.Exception.Message); "[FAIL] $Name : " + $_.Exception.Message }
}
function Get-PowerValue([string]$Sub, [string]$Setting, [bool]$Ac) {
  $out = powercfg /query SCHEME_CURRENT $Sub $Setting 2>&1 | Out-String
  $m = [regex]::Matches($out, '0x[0-9a-fA-F]{8}')
  if ($m.Count -ge 2) {
    $i = $m.Count - 1; if ($Ac) { $i = $m.Count - 2 }
    return [int64][Convert]::ToInt64($m[$i].Value.Substring(2), 16)
  }
  return $null
}
function Get-ActiveScheme {
  $out = powercfg /getactivescheme 2>&1 | Out-String
  $g = [regex]::Match($out, '[0-9a-fA-F]{8}(?:-[0-9a-fA-F]{4}){3}-[0-9a-fA-F]{12}').Value
  if ($g) { return $g }
  return $null
}
  $fwGroups = @('@FirewallAPI.dll,-32752', '@FirewallAPI.dll,-28502')
  $fwOff = @()
  foreach ($g in $fwGroups) { $fwOff += @(Get-NetFirewallRule -Group $g -ErrorAction SilentlyContinue | Where-Object { "$($_.Profile)" -ne 'Public' -and "$($_.Enabled)" -ne 'True' } | ForEach-Object { $_.Name }) }
  if ($domain) { $warn.Add('This PC is domain joined: Group Policy or MDM may override some of these settings.') }
  "Saving the current machine settings (the first backup is kept)..."
  if (-not (Test-Path -LiteralPath $file)) {
    $specs = @(
      @('HKLM:\SOFTWARE\Policies\Microsoft\Windows\Windows Search', 'ConfigureSearchOnTaskbarMode'),
      @('HKLM:\SOFTWARE\Policies\Microsoft\Dsh', 'AllowNewsAndInterests'),
      @('HKLM:\SYSTEM\CurrentControlSet\Control\CrashControl', 'AutoReboot'),
      @('HKLM:\SYSTEM\CurrentControlSet\Control\CrashControl', 'LogEvent'),
      @('HKLM:\SYSTEM\CurrentControlSet\Control\GraphicsDrivers', 'CABCOption'),
      @('HKLM:\SOFTWARE\Microsoft\WindowsUpdate\UX\Settings', 'IsContinuousInnovationOptedIn'),
      @('HKLM:\SOFTWARE\Microsoft\WindowsUpdate\UX\Settings', 'AllowMUUpdateService'),
      @('HKLM:\SOFTWARE\Policies\Microsoft\Windows\WindowsUpdate', 'AllowOptionalContent'))
    $snap = foreach ($s in $specs) { Get-RegSnap $s[0] $s[1] }
    $backup = [pscustomobject]@{ CreatedAt = (Get-Date).ToString('o'); Registry = @($snap); ActivePowerScheme = (Get-ActiveScheme)
      MonitorTimeoutAC = (Get-PowerValue 'SUB_VIDEO' 'VIDEOIDLE' $true); MonitorTimeoutDC = (Get-PowerValue 'SUB_VIDEO' 'VIDEOIDLE' $false)
      SleepTimeoutAC = (Get-PowerValue 'SUB_SLEEP' 'STANDBYIDLE' $true); SleepTimeoutDC = (Get-PowerValue 'SUB_SLEEP' 'STANDBYIDLE' $false); FirewallRules = @($fwOff) }
    $backup | ConvertTo-Json -Depth 6 | Set-Content -LiteralPath $file -Encoding UTF8
    "  saved: $file"
  } else { "  a backup already exists, keeping the original: $file" }
  ""
  Step 'Search taskbar policy' {
    if ($isPro -and [int]$os.BuildNumber -ge 26100) { Set-Dword 'HKLM:\SOFTWARE\Policies\Microsoft\Windows\Windows Search' 'ConfigureSearchOnTaskbarMode' 0 }
    else { $warn.Add('Search policy skipped (needs Pro or higher and Windows 11 24H2 or later); the per-user setting is used instead.') }
  }
  Step 'Widgets policy' {
    if ($isPro -and -not $domain) { Set-Dword 'HKLM:\SOFTWARE\Policies\Microsoft\Dsh' 'AllowNewsAndInterests' 0 }
    else { $warn.Add('Widgets policy skipped (Home edition or domain joined); the per-user setting is used instead.') }
  }
  Step 'High Performance power plan' {
    $hp = '8c5e7fda-e8bf-4a96-9a85-a6e23a8c635c'
    $plans = powercfg /list 2>&1 | Out-String
    if ($plans -notmatch [regex]::Escape($hp)) {
      $dup = powercfg /duplicatescheme SCHEME_MIN 2>&1 | Out-String
      $g = [regex]::Match($dup, '[0-9a-fA-F]{8}(?:-[0-9a-fA-F]{4}){3}-[0-9a-fA-F]{12}').Value
      if (-not $g) { throw 'could not create the High Performance plan' }
      if ((Get-UICulture).TwoLetterISOLanguageName -eq 'pl') { $pn = 'Wysoka wydajność'; $pd = 'Preferuje wydajność, ale może zużywać więcej energii.' } else { $pn = 'High performance'; $pd = 'Favors performance, but may use more energy.' }
      powercfg /changename $g $pn $pd | Out-Null
      powercfg /setacvalueindex $g SUB_PROCESSOR PROCTHROTTLEMIN 100 | Out-Null
      powercfg /setdcvalueindex $g SUB_PROCESSOR PROCTHROTTLEMIN 100 | Out-Null
      powercfg /setacvalueindex $g SUB_PROCESSOR PROCTHROTTLEMAX 100 | Out-Null
      powercfg /setdcvalueindex $g SUB_PROCESSOR PROCTHROTTLEMAX 100 | Out-Null
      powercfg /setacvalueindex $g SUB_PROCESSOR SYSCOOLPOL 1 | Out-Null
      powercfg /setdcvalueindex $g SUB_PROCESSOR SYSCOOLPOL 1 | Out-Null
      powercfg /setacvalueindex $g SUB_DISK DISKIDLE 0 | Out-Null
      powercfg /setdcvalueindex $g SUB_DISK DISKIDLE 0 | Out-Null
      $hp = $g
      "created the plan '$pn' (processor 100%, active cooling, disks never off)"
    }
    powercfg /setactive $hp | Out-Null
    if ($LASTEXITCODE -ne 0) { throw 'powercfg could not activate the plan' }
  }
  Step 'Display off: 15 min on AC, 10 min on battery' {
    powercfg /change monitor-timeout-ac 15; if ($LASTEXITCODE -ne 0) { throw 'powercfg failed' }
    powercfg /change monitor-timeout-dc 10; if ($LASTEXITCODE -ne 0) { throw 'powercfg failed' }
  }
  Step 'Sleep: never on AC, after 1 hour on battery' {
    powercfg /change standby-timeout-ac 0; if ($LASTEXITCODE -ne 0) { throw 'powercfg failed' }
    powercfg /change standby-timeout-dc 60; if ($LASTEXITCODE -ne 0) { throw 'powercfg failed' }
  }
  Step 'System Protection on, 5% disk space for restore points' {
    $d = $env:SystemDrive
    Enable-ComputerRestore -Drive ($d + '\') -ErrorAction Stop
    vssadmin resize shadowstorage /for=$d /on=$d /maxsize=5% | Out-Null
    if ($LASTEXITCODE -ne 0) { throw 'vssadmin could not set the maximum usage' }
  }
  Step 'Startup and Recovery: no automatic restart, log the crash' {
    Set-Dword 'HKLM:\SYSTEM\CurrentControlSet\Control\CrashControl' 'AutoReboot' 0
    Set-Dword 'HKLM:\SYSTEM\CurrentControlSet\Control\CrashControl' 'LogEvent' 1
  }
  Step 'Change brightness based on content: off' {
    if ([int]$os.BuildNumber -ge 22621) { Set-Dword 'HKLM:\SYSTEM\CurrentControlSet\Control\GraphicsDrivers' 'CABCOption' 0; "applies only where the display supports it" }
    else { $warn.Add('Brightness-by-content option skipped (needs Windows 11 22H2 or later).') }
  }
  Step 'Network discovery and File and printer sharing' {
    foreach ($g in $fwGroups) {
      $rules = @(Get-NetFirewallRule -Group $g -ErrorAction SilentlyContinue | Where-Object { "$($_.Profile)" -ne 'Public' })
      if ($rules.Count -eq 0) { $warn.Add('Firewall rule group ' + $g + ' was not found.') } else { $rules | Enable-NetFirewallRule -ErrorAction Stop }
    }
    foreach ($svc in 'fdPHost', 'FDResPub', 'LanmanServer') {
      try { Set-Service -Name $svc -StartupType Automatic -ErrorAction Stop; if ((Get-Service -Name $svc).Status -ne 'Running') { Start-Service -Name $svc -ErrorAction Stop } }
      catch { $warn.Add('Service ' + $svc + ': ' + $_.Exception.Message) }
    }
  }
  ""
  if ($warn.Count -gt 0) { "Notes:"; foreach ($w in $warn) { "  - $w" } }
  "System Protection size and the created power plan are not removed by Restore."
  if ($errors.Count -gt 0) { "Failed steps: " + $errors.Count; $global:LASTEXITCODE = 1 } else { "All machine steps finished. No restart is needed."; $global:LASTEXITCODE = 0 }
  "Undo with: Restore machine settings (admin)."
}

$me = [Security.Principal.WindowsIdentity]::GetCurrent().Name
$active = [string](Get-CimInstance Win32_ComputerSystem).UserName
if ($active -and $me -ne $active) {
  "Stopped: this run is $me, but the signed-in user is $active. Per-user settings would go to the wrong profile."
  "Close the app and start it as $active (a normal start, or Restart as administrator with the same account)."
  $global:LASTEXITCODE = 1
} else {
  $errors = New-Object System.Collections.Generic.List[string]
  $warn = New-Object System.Collections.Generic.List[string]
  $dir = Join-Path $env:LOCALAPPDATA 'ToolsSetupBackup'
  $file = Join-Path $dir 'user.json'
  New-Item -ItemType Directory -Path $dir -Force | Out-Null
function Get-RegSnap([string]$Path, [string]$Name) {
  $exists = $false; $value = $null; $kind = $null
  try { if (Test-Path -LiteralPath $Path) { $key = Get-Item -LiteralPath $Path; if ($key.GetValueNames() -contains $Name) { $exists = $true; $value = $key.GetValue($Name, $null, 'DoNotExpandEnvironmentNames'); $kind = $key.GetValueKind($Name).ToString() } } } catch { }
  [pscustomobject]@{ Path = $Path; Name = $Name; Exists = $exists; Value = $value; Kind = $kind }
}
function Set-Dword([string]$Path, [string]$Name, [int]$Value) {
  if (-not (Test-Path -LiteralPath $Path)) { New-Item -Path $Path -Force -ErrorAction Stop | Out-Null }
  New-ItemProperty -LiteralPath $Path -Name $Name -Value $Value -PropertyType DWord -Force -ErrorAction Stop | Out-Null
}
function Restore-RegSnap($Item) {
  if ($Item.Exists) {
    if (-not (Test-Path -LiteralPath $Item.Path)) { New-Item -Path $Item.Path -Force -ErrorAction Stop | Out-Null }
    $kind = 'String'; if ($Item.Kind) { $kind = $Item.Kind }
    New-ItemProperty -LiteralPath $Item.Path -Name $Item.Name -Value $Item.Value -PropertyType $kind -Force -ErrorAction Stop | Out-Null
  } else { Remove-ItemProperty -LiteralPath $Item.Path -Name $Item.Name -ErrorAction SilentlyContinue }
}
function Step([string]$Name, [scriptblock]$Body) {
  try {
    $o = @(& $Body)
    "[ OK ] $Name"
    foreach ($l in $o) { if ("$l".Trim().Length -gt 0) { "         $l" } }
  } catch { $errors.Add($Name + ': ' + $_.Exception.Message); "[FAIL] $Name : " + $_.Exception.Message }
}
function Restart-Explorer {
  Stop-Process -Name explorer -Force -ErrorAction SilentlyContinue
  Start-Sleep -Seconds 2
  $t = 0
  while ($t -lt 15 -and -not (Get-Process -Name explorer -ErrorAction SilentlyContinue)) { Start-Sleep -Seconds 1; $t++ }
  if (-not (Get-Process -Name explorer -ErrorAction SilentlyContinue)) { Start-Process explorer.exe }
}
function Set-WidgetsOffViaSettings {
  Add-Type -AssemblyName UIAutomationClient -ErrorAction Stop
  Add-Type -AssemblyName UIAutomationTypes -ErrorAction Stop
  Start-Process 'ms-settings:taskbar'
  $root = [System.Windows.Automation.AutomationElement]::RootElement
  $winCond = New-Object System.Windows.Automation.PropertyCondition([System.Windows.Automation.AutomationElement]::ControlTypeProperty, [System.Windows.Automation.ControlType]::Window)
  $all = [System.Windows.Automation.Condition]::TrueCondition
  $pattern = '(?i)widgets|wid' + [char]0x017C + 'et|widzet'
  $labels = @()
  for ($attempt = 0; $attempt -lt 20 -and $labels.Count -eq 0; $attempt++) {
    foreach ($w in $root.FindAll([System.Windows.Automation.TreeScope]::Children, $winCond)) {
      try {
        $hits = @($w.FindAll([System.Windows.Automation.TreeScope]::Descendants, $all) | Where-Object { try { $_.Current.Name -match $pattern } catch { $false } })
        if ($hits.Count -gt 0) { $labels = $hits; break }
      } catch { }
    }
    if ($labels.Count -eq 0) { Start-Sleep -Milliseconds 500 }
  }
  if ($labels.Count -eq 0) { throw 'the Widgets control was not found in Settings; switch it off manually' }
  $walker = [System.Windows.Automation.TreeWalker]::ControlViewWalker
  foreach ($label in $labels) {
    $cands = @($label)
    try { $parent = $walker.GetParent($label); if ($parent) { $cands += $parent; foreach ($c in $parent.FindAll([System.Windows.Automation.TreeScope]::Children, $all)) { $cands += $c } } } catch { }
    foreach ($c in $cands) {
      try {
        $toggle = $null
        if ($c.TryGetCurrentPattern([System.Windows.Automation.TogglePattern]::Pattern, [ref]$toggle)) {
          if ($toggle.Current.ToggleState -eq [System.Windows.Automation.ToggleState]::Off) { return 'already Off in Settings' }
          $toggle.Toggle(); Start-Sleep -Milliseconds 1200
          if ($toggle.Current.ToggleState -eq [System.Windows.Automation.ToggleState]::Off) { return 'switched Off through the Settings page' }
        }
      } catch { }
    }
  }
  throw 'the Widgets toggle could not be switched; the Settings page was left open for you'
}
function Set-WidgetsOff {
  $path = 'HKCU:\Software\Microsoft\Windows\CurrentVersion\Explorer\Advanced'
  $cur = $null
  try { $cur = [int](Get-ItemProperty -LiteralPath $path -Name 'TaskbarDa' -ErrorAction Stop).TaskbarDa } catch { }
  if ($null -ne $cur -and $cur -eq 0) { return 'already Off' }
  try { Set-Dword $path 'TaskbarDa' 0; if ([int](Get-ItemProperty -LiteralPath $path -Name 'TaskbarDa' -ErrorAction Stop).TaskbarDa -eq 0) { return 'set in the registry' } } catch { }
  try { $null = reg.exe add 'HKCU\Software\Microsoft\Windows\CurrentVersion\Explorer\Advanced' /v TaskbarDa /t REG_DWORD /d 0 /f 2>&1; if ($LASTEXITCODE -eq 0 -and [int](Get-ItemProperty -LiteralPath $path -Name 'TaskbarDa' -ErrorAction Stop).TaskbarDa -eq 0) { return 'set with reg.exe' } } catch { }
  return (Set-WidgetsOffViaSettings)
}
  "Profile: $me"
  "Saving the current user settings (the first backup is kept)..."
  if (-not (Test-Path -LiteralPath $file)) {
    $specs = @(
      @('HKCU:\Software\Microsoft\Windows\CurrentVersion\Themes\Personalize', 'AppsUseLightTheme'),
      @('HKCU:\Software\Microsoft\Windows\CurrentVersion\Themes\Personalize', 'SystemUsesLightTheme'),
      @('HKCU:\Control Panel\Desktop', 'Wallpaper'),
      @('HKCU:\Software\Microsoft\Windows\CurrentVersion\Explorer\Advanced', 'LaunchTo'),
      @('HKCU:\Software\Microsoft\Windows\CurrentVersion\Explorer\Advanced', 'UseCompactMode'),
      @('HKCU:\Software\Microsoft\Windows\CurrentVersion\Explorer\Advanced', 'TaskbarDa'),
      @('HKCU:\Software\Microsoft\Windows\CurrentVersion\Explorer\Advanced', 'ShowTaskViewButton'),
      @('HKCU:\Software\Microsoft\Windows\CurrentVersion\Explorer\Advanced', 'Start_TrackDocs'),
      @('HKCU:\Software\Microsoft\Windows\CurrentVersion\Start', 'ShowRecentList'),
      @('HKCU:\Software\Microsoft\Windows\CurrentVersion\Start', 'AllAppsViewMode'),
      @('HKCU:\Software\Microsoft\Windows\CurrentVersion\Search', 'SearchboxTaskbarMode'))
    $snap = foreach ($s in $specs) { Get-RegSnap $s[0] $s[1] }
    [pscustomobject]@{ CreatedAt = (Get-Date).ToString('o'); Registry = @($snap) } | ConvertTo-Json -Depth 6 | Set-Content -LiteralPath $file -Encoding UTF8
    "  saved: $file"
  } else { "  a backup already exists, keeping the original: $file" }
  ""
  Step 'Dark mode' {
    Set-Dword 'HKCU:\Software\Microsoft\Windows\CurrentVersion\Themes\Personalize' 'AppsUseLightTheme' 0
    Set-Dword 'HKCU:\Software\Microsoft\Windows\CurrentVersion\Themes\Personalize' 'SystemUsesLightTheme' 0
  }
  Step 'Built-in Windows wallpaper' {
    $wp = @((Join-Path $env:SystemRoot 'Web\Wallpaper\Windows\img19.jpg'), (Join-Path $env:SystemRoot 'Web\Wallpaper\Windows\img0.jpg')) | Where-Object { Test-Path -LiteralPath $_ } | Select-Object -First 1
    if (-not $wp) { throw 'no built-in wallpaper file found; the wallpaper was left unchanged' }
    Set-ItemProperty -LiteralPath 'HKCU:\Control Panel\Desktop' -Name Wallpaper -Value $wp -ErrorAction Stop
Add-Type -TypeDefinition @'
using System.Runtime.InteropServices;
public class ToolsWallpaper {
  [DllImport("user32.dll", SetLastError=true, CharSet=CharSet.Auto)]
  public static extern bool SystemParametersInfo(int uAction, int uParam, string lpvParam, int fuWinIni);
}
'@ -ErrorAction SilentlyContinue
    [void][ToolsWallpaper]::SystemParametersInfo(20, 0, $wp, 3)
  }
  Step 'File Explorer opens to This PC' { Set-Dword 'HKCU:\Software\Microsoft\Windows\CurrentVersion\Explorer\Advanced' 'LaunchTo' 1 }
  Step 'File Explorer Compact view' { Set-Dword 'HKCU:\Software\Microsoft\Windows\CurrentVersion\Explorer\Advanced' 'UseCompactMode' 1 }
  Step 'Taskbar Search hidden' { Set-Dword 'HKCU:\Software\Microsoft\Windows\CurrentVersion\Search' 'SearchboxTaskbarMode' 0 }
  Step 'Taskbar Task View hidden' { Set-Dword 'HKCU:\Software\Microsoft\Windows\CurrentVersion\Explorer\Advanced' 'ShowTaskViewButton' 0 }
  Step 'Taskbar Widgets hidden' { Set-WidgetsOff }
  Step 'Start menu: recent items hidden' {
    Set-Dword 'HKCU:\Software\Microsoft\Windows\CurrentVersion\Explorer\Advanced' 'Start_TrackDocs' 0
    Set-Dword 'HKCU:\Software\Microsoft\Windows\CurrentVersion\Start' 'ShowRecentList' 0
  }
  Step 'Start menu: All apps shown as a list' { Set-Dword 'HKCU:\Software\Microsoft\Windows\CurrentVersion\Start' 'AllAppsViewMode' 2 }
