  $checks = @(
    @('Dark mode', 'HKCU:\Software\Microsoft\Windows\CurrentVersion\Themes\Personalize', 'SystemUsesLightTheme', 0),
    @('Explorer opens to This PC', 'HKCU:\Software\Microsoft\Windows\CurrentVersion\Explorer\Advanced', 'LaunchTo', 1),
    @('Explorer Compact view', 'HKCU:\Software\Microsoft\Windows\CurrentVersion\Explorer\Advanced', 'UseCompactMode', 1),
    @('Taskbar Search hidden', 'HKCU:\Software\Microsoft\Windows\CurrentVersion\Search', 'SearchboxTaskbarMode', 0),
    @('Taskbar Widgets hidden', 'HKCU:\Software\Microsoft\Windows\CurrentVersion\Explorer\Advanced', 'TaskbarDa', 0),
    @('Taskbar Task View hidden', 'HKCU:\Software\Microsoft\Windows\CurrentVersion\Explorer\Advanced', 'ShowTaskViewButton', 0),
    @('Start: recent items hidden', 'HKCU:\Software\Microsoft\Windows\CurrentVersion\Explorer\Advanced', 'Start_TrackDocs', 0),
    @('Start: recently added apps hidden', 'HKCU:\Software\Microsoft\Windows\CurrentVersion\Start', 'ShowRecentList', 0),
    @('Start: All apps as a list', 'HKCU:\Software\Microsoft\Windows\CurrentVersion\Start', 'AllAppsViewMode', 2))
  foreach ($c in $checks) {
    try { $v = (Get-ItemProperty -LiteralPath $c[1] -Name $c[2] -ErrorAction Stop).($c[2]); if ([int]$v -eq $c[3]) { "[ OK ] verified: " + $c[0] } else { $warn.Add('verification failed for ' + $c[0] + ' (expected ' + $c[3] + ', got ' + $v + ')') } }
    catch { $warn.Add('could not verify ' + $c[0]) }
