function Get-SettingsWindows {
  Add-Type -AssemblyName UIAutomationClient -ErrorAction Stop
  Add-Type -AssemblyName UIAutomationTypes -ErrorAction Stop
  $root = [System.Windows.Automation.AutomationElement]::RootElement
  $winCond = New-Object System.Windows.Automation.PropertyCondition([System.Windows.Automation.AutomationElement]::ControlTypeProperty, [System.Windows.Automation.ControlType]::Window)
  $found = @()
  foreach ($w in $root.FindAll([System.Windows.Automation.TreeScope]::Children, $winCond)) {
    try { if ($w.Current.ClassName -eq 'ApplicationFrameWindow' -and $w.Current.Name -match '^(Settings|Ustawienia)') { $found += $w } } catch { }
  }
  return ,$found
}
function Invoke-SettingsButton([string]$Pattern, [int]$TimeoutSec) {
  Add-Type -AssemblyName UIAutomationClient -ErrorAction Stop
  Add-Type -AssemblyName UIAutomationTypes -ErrorAction Stop
  $btnCond = New-Object System.Windows.Automation.PropertyCondition([System.Windows.Automation.AutomationElement]::ControlTypeProperty, [System.Windows.Automation.ControlType]::Button)
  $deadline = (Get-Date).AddSeconds($TimeoutSec)
  while ((Get-Date) -lt $deadline) {
    foreach ($w in (Get-SettingsWindows)) {
      try {
        foreach ($b in $w.FindAll([System.Windows.Automation.TreeScope]::Descendants, $btnCond)) {
          $n = ''; try { $n = $b.Current.Name } catch { }
          if ($n -match $Pattern) {
            $inv = $null
            if ($b.TryGetCurrentPattern([System.Windows.Automation.InvokePattern]::Pattern, [ref]$inv)) { $inv.Invoke(); return $n }
          }
        }
      } catch { }
    }
    Start-Sleep -Milliseconds 700
  }
  return $null
}
