function Select-OptionalUpdates([int]$TimeoutSec) {
  Add-Type -AssemblyName UIAutomationClient -ErrorAction Stop
  Add-Type -AssemblyName UIAutomationTypes -ErrorAction Stop
  $all = [System.Windows.Automation.Condition]::TrueCondition
  $cbCond = New-Object System.Windows.Automation.PropertyCondition([System.Windows.Automation.AutomationElement]::ControlTypeProperty, [System.Windows.Automation.ControlType]::CheckBox)
  $deadline = (Get-Date).AddSeconds($TimeoutSec)
  $expanded = 0; $selected = 0
  while ((Get-Date) -lt $deadline -and $selected -eq 0) {
    foreach ($w in (Get-SettingsWindows)) {
      try {
        foreach ($el in $w.FindAll([System.Windows.Automation.TreeScope]::Descendants, $all)) {
          $p = $null
          if ($el.TryGetCurrentPattern([System.Windows.Automation.ExpandCollapsePattern]::Pattern, [ref]$p)) {
            if ($p.Current.ExpandCollapseState -eq [System.Windows.Automation.ExpandCollapseState]::Collapsed) { $p.Expand(); $expanded++ }
          }
        }
        Start-Sleep -Milliseconds 800
        foreach ($cb in $w.FindAll([System.Windows.Automation.TreeScope]::Descendants, $cbCond)) {
          $t = $null
          if ($cb.TryGetCurrentPattern([System.Windows.Automation.TogglePattern]::Pattern, [ref]$t)) {
            if ($t.Current.ToggleState -eq [System.Windows.Automation.ToggleState]::Off) { $t.Toggle(); $selected++ }
          }
        }
      } catch { }
    }
    if ($selected -eq 0) { Start-Sleep -Milliseconds 700 }
  }
  return "expanded $expanded group(s), selected $selected update(s)"
}
