Show-Section 'MOTHERBOARD' { Get-CimInstance Win32_BaseBoard | Select-Object Manufacturer,Product,SerialNumber,Version | Format-List }
Show-Section 'BIOS' { Get-CimInstance Win32_BIOS | Select-Object Manufacturer,SMBIOSBIOSVersion,ReleaseDate | Format-List }
Show-Section 'CPU' { Get-CimInstance Win32_Processor | Select-Object Name,NumberOfCores,NumberOfLogicalProcessors,MaxClockSpeed | Format-List }
Show-Section 'RAM MODULES' { Get-CimInstance Win32_PhysicalMemory | Select-Object BankLabel,@{N='GB';E={[math]::Round($_.Capacity/1GB,1)}},Speed,Manufacturer,PartNumber | Format-Table -AutoSize }
