Get-ChildItem -LiteralPath $out | Select-Object Name,@{N='KB';E={[math]::Round($_.Length / 1KB)}} | Format-Table -AutoSize

$a = Get-CimInstance Win32_PhysicalMemoryArray -ErrorAction SilentlyContinue | Select-Object -First 1
$m = @(Get-CimInstance Win32_PhysicalMemory -ErrorAction SilentlyContinue)
if (-not $a) { "The firmware does not report memory slot information." } else {
  $types = @{18='DDR';19='DDR2';20='DDR2 FB-DIMM';24='DDR3';26='DDR4';27='LPDDR';28='LPDDR2';29='LPDDR3';30='LPDDR4';34='DDR5';35='LPDDR5'}
  $cap = $a.MaxCapacity; if ($a.MaxCapacityEx) { $cap = $a.MaxCapacityEx }
  "Memory slots: {0}   in use: {1}   free: {2}" -f $a.MemoryDevices, $m.Count, ($a.MemoryDevices - $m.Count)
  "Maximum supported capacity: {0} GB" -f [math]::Round($cap / 1MB, 0)
  ""
  $m | Select-Object DeviceLocator,BankLabel,@{N='GB';E={[math]::Round($_.Capacity / 1GB, 1)}},@{N='Type';E={ $types[[int]$_.SMBIOSMemoryType] }},Speed,ConfiguredClockSpeed,Manufacturer,PartNumber | Format-Table -AutoSize
}

$dest = "FOLDER_PATH"
$root = Join-Path $dest ('ProfileBackup_' + $env:USERNAME + '_' + (Get-Date -Format 'yyyyMMdd'))
New-Item -ItemType Directory -Path $root -Force | Out-Null
$failed = $false
foreach ($pair in @(@('Desktop', [Environment]::GetFolderPath('Desktop')), @('Documents', [Environment]::GetFolderPath('MyDocuments')))) {
  "Copying " + $pair[0] + " ..."
  robocopy $pair[1] (Join-Path $root $pair[0]) /E /R:1 /W:1 /XJ /NP /NFL /NDL /NJH | Out-Null
  if ($LASTEXITCODE -ge 8) { $failed = $true; "  FAILED (robocopy exit code $LASTEXITCODE)" } else { "  OK" }
}
if ($failed) { $global:LASTEXITCODE = 1 } else { $global:LASTEXITCODE = 0 }
"Backup folder: $root"

$g = Get-CimInstance Win32_VideoController -ErrorAction SilentlyContinue
if (-not $g) { "No graphics adapter was reported." } else {
  $g | Select-Object Name,VideoProcessor,DriverVersion,DriverDate,Status,CurrentHorizontalResolution,CurrentVerticalResolution,CurrentRefreshRate | Format-List
  foreach ($a in $g) {
    if ($a.Name -match 'Basic Display|Remote Display|Hyper-V|Virtual|Mirror|Indirect') { continue }
    $q = [uri]::EscapeDataString("$($a.Name) driver download").Replace('%20','+')
    "$($a.Name) - find a newer driver here:"
    "https://www.google.com/search?q=$q"
  }
}

$f = @(Get-CimInstance -Namespace root/wmi -ClassName BatteryFullChargedCapacity -ErrorAction SilentlyContinue)
$s = @(Get-CimInstance -Namespace root/wmi -ClassName BatteryStaticData -ErrorAction SilentlyContinue)
if ($f.Count -eq 0 -or $s.Count -eq 0) { "No battery data available (desktop PC, the driver does not expose it, or run as Administrator)." } else {
  for ($i = 0; $i -lt $f.Count; $i++) {
    $design = $s[[math]::Min($i, $s.Count - 1)].DesignedCapacity; $full = $f[$i].FullChargedCapacity
    if ($design -gt 0) { "Battery {0}: design {1} mWh, full charge {2} mWh -> health {3}%, wear {4}%" -f ($i + 1), $design, $full, [math]::Round($full / $design * 100, 1), [math]::Round(100 - $full / $design * 100, 1) }
  }
}

$e = Get-WinEvent -FilterHashtable @{LogName='System'; Id=1001; ProviderName='Microsoft-Windows-WER-SystemErrorReporting'} -MaxEvents 3 -ErrorAction SilentlyContinue
if ($e) { $e | ForEach-Object { "{0}  {1}" -f $_.TimeCreated, ($_.Message -replace '\r?\n', ' ') } } else { "No bluescreen reports found in the System log." }
$d = Get-ChildItem (Join-Path $env:SystemRoot 'Minidump') -ErrorAction SilentlyContinue | Sort-Object LastWriteTime -Descending | Select-Object -First 5 Name,Length,LastWriteTime
""
if ($d) { "Latest minidumps:"; $d | Format-Table -AutoSize } else { "No minidump files found in " + (Join-Path $env:SystemRoot 'Minidump') + " (needs Administrator, or none were saved)." }

$id = "EVENT_ID"
if ($id -notmatch '^\d+$') { "Enter the event ID as a number, for example 41." } else {
  $e = Get-WinEvent -FilterHashtable @{LogName='System','Application'; Id=[int]$id; StartTime=(Get-Date).AddDays(-7)} -MaxEvents 50 -ErrorAction SilentlyContinue
  if ($e) { $e | Select-Object TimeCreated,LogName,ProviderName,@{N='Message';E={($_.Message -split '\r?\n')[0]}} | Format-Table -Wrap -AutoSize } else { "No events with ID $id in the last 7 days." }
}

$h = "HOURS"
if ($h -notmatch '^\d+$') { "Enter the number of hours, for example 24." } else {
  $e = Get-WinEvent -FilterHashtable @{LogName='System','Application'; Level=1,2,3; StartTime=(Get-Date).AddHours(-[int]$h)} -MaxEvents 100 -ErrorAction SilentlyContinue
  if ($e) { $e | Select-Object TimeCreated,LevelDisplayName,ProviderName,Id,@{N='Message';E={($_.Message -split '\r?\n')[0]}} | Format-Table -Wrap -AutoSize } else { "No errors or warnings in the last $h hours." }
}

function Restart-Explorer {
  Stop-Process -Name explorer -Force -ErrorAction SilentlyContinue
  Start-Sleep -Seconds 2
  $t = 0
  while ($t -lt 15 -and -not (Get-Process -Name explorer -ErrorAction SilentlyContinue)) { Start-Sleep -Seconds 1; $t++ }
  if (-not (Get-Process -Name explorer -ErrorAction SilentlyContinue)) { Start-Process explorer.exe }
}
Restart-Explorer
"Explorer restarted."

$s = Get-AppxPackage -Name Microsoft.WindowsStore
if (-not $s) { "The Microsoft Store package was not found for this user." } else {
  $s | ForEach-Object { Add-AppxPackage -DisableDevelopmentMode -Register (Join-Path $_.InstallLocation 'AppXManifest.xml') -ErrorAction SilentlyContinue }
  "Microsoft Store re-registered."
}

$n = 0
Get-AppxPackage | ForEach-Object { if ($_.InstallLocation) { Add-AppxPackage -DisableDevelopmentMode -Register (Join-Path $_.InstallLocation 'AppXManifest.xml') -ErrorAction SilentlyContinue; $n++ } }
"Re-registered $n app packages. Sign out and in if the Start menu still misbehaves."

$m = Get-SmbMapping -ErrorAction SilentlyContinue
if ($m) { "Mapped drives:"; $m | Select-Object LocalPath,RemotePath,Status | Format-Table -AutoSize } else { "No mapped network drives." }
$c = Get-SmbConnection -ErrorAction SilentlyContinue
if ($c) { ""; "Open SMB connections:"; $c | Select-Object ServerName,ShareName,UserName,Dialect | Format-Table -AutoSize }

$cfg = Get-NetIPConfiguration | Where-Object { $_.IPv4DefaultGateway -and $_.NetAdapter.Status -eq 'Up' } | Select-Object -First 1
if (-not $cfg) { "No active network with a default gateway was found." } else {
  $ip = $cfg.IPv4Address.IPAddress
  $base = ($ip -split '\.')[0..2] -join '.'
  "Scanning $base.1 - $base.254 from $ip (about 8 seconds)..."
  $jobs = 1..254 | ForEach-Object { $p = New-Object System.Net.NetworkInformation.Ping; [pscustomobject]@{ Ip = "$base.$_"; Task = $p.SendPingAsync("$base.$_", 800) } }
  try { [void][System.Threading.Tasks.Task]::WaitAll([System.Threading.Tasks.Task[]]@($jobs | ForEach-Object { $_.Task }), 8000) } catch { }
  $alive = @($jobs | Where-Object { $_.Task.Status -eq 'RanToCompletion' -and $_.Task.Result.Status -eq 'Success' } | ForEach-Object { $_.Ip })
  $nb = @(Get-NetNeighbor -AddressFamily IPv4 -ErrorAction SilentlyContinue | Where-Object { $_.IPAddress -like "$base.*" -and $_.LinkLayerAddress -and $_.LinkLayerAddress -ne 'FF-FF-FF-FF-FF-FF' -and "$($_.State)" -ne 'Unreachable' -and "$($_.State)" -ne 'Incomplete' })
  $all = (@($alive) + @($nb | ForEach-Object { $_.IPAddress })) | Sort-Object -Unique { [version]$_ }
  $rows = foreach ($a in $all) { $m = $nb | Where-Object { $_.IPAddress -eq $a } | Select-Object -First 1; [pscustomobject]@{ IP = $a; MAC = $m.LinkLayerAddress; AnsweredPing = ($alive -contains $a) } }
  $rows | Format-Table -AutoSize
  "Found " + @($rows).Count + " devices. Look up the MAC vendor prefix to identify unknown devices."
}

$cs = Get-CimInstance Win32_ComputerSystem
"Computer: " + $cs.Name
if ($cs.PartOfDomain) { "Domain joined: " + $cs.Domain } else { "Not domain joined (workgroup: " + $cs.Workgroup + ")" }
$j = dsregcmd /status 2>&1 | Select-String -Pattern '^\s*(AzureAdJoined|EnterpriseJoined|DomainJoined|DomainName|TenantName|WorkplaceJoined)\s*:'
if ($j) { ""; "Entra ID (Azure AD) join:"; $j | ForEach-Object { "  " + $_.Line.Trim() } } else { "dsregcmd is not available on this PC." }

$p = Join-Path ([Environment]::GetFolderPath('Desktop')) 'GPReport.html'
gpresult /h $p /f
if (Test-Path -LiteralPath $p) { Start-Process $p; "Saved to $p" } else { "The report could not be created (run as Administrator, or this PC has no policy data)." }

if (-not (Get-CimInstance Win32_ComputerSystem).PartOfDomain) { "This PC is not domain joined." } else {
  try { if (Test-ComputerSecureChannel) { "Secure channel to the domain: OK" } else { "Secure channel to the domain: BROKEN - repair it with a domain admin account." ; $global:LASTEXITCODE = 1 } }
  catch { "The test could not run: " + $_.Exception.Message }
}

$items = Get-CimInstance Win32_StartupCommand -ErrorAction SilentlyContinue
if (-not $items) { "No startup programs were found." } else {
  $me = [Security.Principal.WindowsIdentity]::GetCurrent().User.Value
  function Test-Approved($hive, $name) {
    foreach ($k in 'Run','Run32','StartupFolder') {
      $p = $hive + ':\Software\Microsoft\Windows\CurrentVersion\Explorer\StartupApproved\' + $k
      if (Test-Path $p) {
        $props = Get-ItemProperty $p
        foreach ($n in @($name, ($name + '.lnk'))) {
          $v = $props.$n
          if ($v -is [byte[]] -and $v.Length -gt 0) { return (($v[0] -band 1) -eq 0) }
        }
      }
    }
    return $true
  }
  $rows = foreach ($i in $items) {
    $loc = [string]$i.Location
    $hive = ''
    if ($loc -match '^HKU\\S-1-5-(18|19|20)\\') { $scope = 'System account' }
    elseif ($loc -match '^HKU\\') { if ($loc.StartsWith('HKU\' + $me + '\')) { $scope = 'Current user'; $hive = 'HKCU' } else { $scope = 'Other user' } }
    elseif ($loc -eq 'Startup') { $scope = 'Current user'; $hive = 'HKCU' }
    else { $scope = 'All users'; $hive = 'HKLM' }
    if ($hive) { if (Test-Approved $hive $i.Name) { $on = 'Yes' } else { $on = 'No' } } else { $on = '?' }
    [pscustomobject]@{ Name = $i.Name; Enabled = $on; Scope = $scope; Command = $i.Command }
  }
  $hidden = @($rows | Where-Object { $_.Scope -eq 'System account' }).Count
  $rows | Where-Object { $_.Scope -ne 'System account' } | Sort-Object Scope, Name | Format-Table -Wrap -AutoSize
  if ($hidden) { "Hidden: $hidden leftover entries of system accounts (Local Service / Network Service) - they are not real startup programs." }
}

$virtual = 'Print to PDF|PDF|XPS|OneNote|Fax|Send to|Snagit|Remote Desktop|Universal Print'
function Get-PrinterSearchName($x) {
  $n = [string]$x.DriverName
  if (-not $n -or $n -match 'Class Driver|Generic|Microsoft|Universal') { $n = [string]$x.Name }
  $n = ($n -split '\\')[-1]
  $n = $n -replace '\s*\((Copy|redirected)[^)]*\)', ''
  $n = $n -replace '\s+PCL\s*6?\b', ''
  return $n.Trim()
}
$p = Get-Printer -ErrorAction SilentlyContinue
if (-not $p) { "No printers are installed." } else {
  $p | Select-Object Name,DriverName,PortName,PrinterStatus,Shared | Format-Table -AutoSize
  $names = foreach ($x in $p) { if (($x.Name + ' ' + $x.DriverName) -match $virtual) { continue }; Get-PrinterSearchName $x }
  foreach ($name in ($names | Sort-Object -Unique)) {
    $q = [uri]::EscapeDataString("$name driver download").Replace('%20','+')
    "$name - find a newer driver here:"
    "https://www.google.com/search?q=$q"
  }
}

$virtual = 'Print to PDF|PDF|XPS|OneNote|Fax|Send to|Snagit|Remote Desktop|Universal Print'
function Get-PrinterSearchName($x) {
  $n = [string]$x.DriverName
  if (-not $n -or $n -match 'Class Driver|Generic|Microsoft|Universal') { $n = [string]$x.Name }
  $n = ($n -split '\\')[-1]
  $n = $n -replace '\s*\((Copy|redirected)[^)]*\)', ''
  $n = $n -replace '\s+PCL\s*6?\b', ''
  return $n.Trim()
}
$d = Get-CimInstance Win32_Printer -ErrorAction SilentlyContinue | Where-Object Default
if (-not $d) { "No default printer is set." } else {
  "Default printer: " + $d.Name
  if (($d.Name + ' ' + $d.DriverName) -notmatch $virtual) {
    $name = Get-PrinterSearchName $d
    $q = [uri]::EscapeDataString("$name driver download").Replace('%20','+')
    "$name - find a newer driver here:"
    "https://www.google.com/search?q=$q"
  }
}

$s = Get-MpComputerStatus -ErrorAction SilentlyContinue
if (-not $s -or -not $s.AMServiceEnabled -or -not $s.AntivirusEnabled) {
  $av = (Get-CimInstance -Namespace root/SecurityCenter2 -ClassName AntiVirusProduct -ErrorAction SilentlyContinue | ForEach-Object { $_.displayName }) -join ", "
  "Microsoft Defender Antivirus is turned off or not available, so it cannot scan."
  if ($av) { "Registered antivirus: $av - that product is probably handling protection; use its own scanner." }
  "Check Windows Security > Virus & threat protection."
  $global:LASTEXITCODE = 1
} else {
  try { Start-MpScan -ScanType QuickScan -ErrorAction Stop; "Quick scan finished." }
  catch { "The scan could not run: " + $_.Exception.Message; "Error 0x800106ba means the Defender service is not running - check Windows Security."; $global:LASTEXITCODE = 1 }
}

$s = Get-MpComputerStatus -ErrorAction SilentlyContinue
if (-not $s -or -not $s.AMServiceEnabled -or -not $s.AntivirusEnabled) {
  $av = (Get-CimInstance -Namespace root/SecurityCenter2 -ClassName AntiVirusProduct -ErrorAction SilentlyContinue | ForEach-Object { $_.displayName }) -join ", "
  "Microsoft Defender Antivirus is turned off or not available, so it cannot scan."
  if ($av) { "Registered antivirus: $av - that product is probably handling protection; use its own scanner." }
  "Check Windows Security > Virus & threat protection."
  $global:LASTEXITCODE = 1
} else {
  try { Start-MpScan -ScanType FullScan -ErrorAction Stop; "Full scan finished." }
  catch { "The scan could not run: " + $_.Exception.Message; "Error 0x800106ba means the Defender service is not running - check Windows Security."; $global:LASTEXITCODE = 1 }
}

try { $v = Get-BitLockerVolume -ErrorAction Stop
  $rows = foreach ($x in $v) { foreach ($k in $x.KeyProtector) { [pscustomobject]@{ Drive = $x.MountPoint; Type = $k.KeyProtectorType; ProtectorId = $k.KeyProtectorId } } }
  if ($rows) { $rows | Format-Table -AutoSize } else { "No key protectors found." }
} catch { "BitLocker information is not available (run as Administrator, or this Windows edition has no BitLocker)." }

try { $v = Get-BitLockerVolume -ErrorAction Stop
  $rows = foreach ($x in $v) { foreach ($k in $x.KeyProtector) { if ($k.KeyProtectorType -eq 'RecoveryPassword') { [pscustomobject]@{ Drive = $x.MountPoint; ProtectorId = $k.KeyProtectorId; RecoveryPassword = $k.RecoveryPassword } } } }
  if ($rows) { $rows | Format-List } else { "No recovery passwords found." }
} catch { "BitLocker information is not available (run as Administrator, or this Windows edition has no BitLocker)." }

$root = "FOLDER_PATH"
if (-not (Test-Path -LiteralPath $root -PathType Container)) { "Folder not found: $root" } else {
  "Scanning $root - this can take a few minutes..."
  Get-ChildItem -LiteralPath $root -Directory -Force -ErrorAction SilentlyContinue | ForEach-Object {
    $s = (Get-ChildItem -LiteralPath $_.FullName -Recurse -File -Force -ErrorAction SilentlyContinue | Measure-Object Length -Sum).Sum
    [pscustomobject]@{ Folder = $_.FullName; SizeGB = [math]::Round(([long]$s) / 1GB, 2) }
  } | Sort-Object SizeGB -Descending | Select-Object -First 15 | Format-Table -AutoSize
}

function Show-Section($t, [scriptblock]$b) { Write-Output ''; Write-Output ('==================== ' + $t + ' ===================='); $r = (& $b 2>&1 | Out-String -Width 250).TrimEnd(); if ($r) { Write-Output $r } else { Write-Output '(nothing found or not available on this PC)' } }
Write-Output ('PC REPAIR TOOLKIT - SYSTEM REPORT   ' + (Get-Date))
Write-Output ('Computer: ' + $env:COMPUTERNAME + '   User: ' + $env:USERNAME)
Show-Section 'OPERATING SYSTEM' { Get-CimInstance Win32_OperatingSystem | Select-Object Caption,Version,BuildNumber,OSArchitecture,InstallDate,LastBootUpTime | Format-List }
Show-Section 'MOTHERBOARD' { Get-CimInstance Win32_BaseBoard | Select-Object Manufacturer,Product,SerialNumber,Version | Format-List }
Show-Section 'BIOS' { Get-CimInstance Win32_BIOS | Select-Object Manufacturer,SMBIOSBIOSVersion,ReleaseDate | Format-List }
Show-Section 'CPU' { Get-CimInstance Win32_Processor | Select-Object Name,NumberOfCores,NumberOfLogicalProcessors,MaxClockSpeed | Format-List }
Show-Section 'RAM MODULES' { Get-CimInstance Win32_PhysicalMemory | Select-Object BankLabel,@{N='GB';E={[math]::Round($_.Capacity/1GB,1)}},Speed,Manufacturer,PartNumber | Format-Table -AutoSize }
Show-Section 'PHYSICAL DISKS' { Get-PhysicalDisk | Select-Object FriendlyName,MediaType,HealthStatus,OperationalStatus,@{N='GB';E={[math]::Round($_.Size/1GB)}} | Format-Table -AutoSize }
Show-Section 'VOLUMES' { Get-PSDrive -PSProvider FileSystem | Select-Object Name,@{N='Free_GB';E={[math]::Round($_.Free/1GB,1)}},@{N='Total_GB';E={[math]::Round(($_.Used+$_.Free)/1GB,1)}} | Format-Table -AutoSize }
Show-Section 'GPU' { Get-CimInstance Win32_VideoController | Select-Object Name,DriverVersion,DriverDate,Status | Format-List }
Show-Section 'NETWORK' { Get-NetIPConfiguration }
Show-Section 'PRINTERS' { Get-Printer | Select-Object Name,DriverName,PortName,PrinterStatus | Format-Table -AutoSize }
Show-Section 'STARTUP PROGRAMS' { Get-CimInstance Win32_StartupCommand | Select-Object Caption,Command,Location | Format-Table -AutoSize }
Show-Section 'DEVICES WITH ERRORS' { Get-CimInstance Win32_PnPEntity | Where-Object ConfigManagerErrorCode -ne 0 | Select-Object Name,ConfigManagerErrorCode | Format-Table -AutoSize }
Show-Section 'RECENT SYSTEM ERRORS' { Get-WinEvent -FilterHashtable @{LogName='System';Level=2} -MaxEvents 10 -ErrorAction SilentlyContinue | Format-List TimeCreated,Id,ProviderName,Message }
Show-Section 'DEFENDER' { Get-MpComputerStatus | Select-Object AntivirusEnabled,RealTimeProtectionEnabled,AntivirusSignatureLastUpdated | Format-List }
